library(edgeR)
library(RUVSeq)

source("scripts/lib/common.R")


# Counts and exon-union lengths used in the RNA-seq analysis.
# An optional argument supplies counts generated by 00_rnaseq_reads.sh.

args <- commandArgs(trailingOnly = TRUE)
count_file <- if (length(args)) args[1] else ref("rna_counts.csv.gz")

gcm <- as.matrix(read.csv(count_file, row.names = 1, check.names = FALSE))
s <- samples("rnaseq")
gcm <- gcm[, s$library]
colnames(gcm) <- s$analysis

grp <- substr(colnames(gcm), 1, 3)

df <- data.frame(
  Sample = colnames(gcm),
  Replicate = rep(1:3, 13),
  Group = grp,
  Time = substr(grp, 1, 1),
  Condition = substr(grp, 3, 3)
)

lengths <- read_tsv(ref("gene_lengths.tsv"))
exl <- structure(lengths$Length, names = lengths$Gene)


# Estimate dispersion and obtain deviance residuals.

gdge <- DGEList(gcm, group = grp)
gdge <- gdge[filterByExpr(gdge, group = grp), , keep.lib.sizes = FALSE]
gdge <- calcNormFactors(gdge)
gdge <- estimateDisp(gdge)
gdge$genes <- data.frame(Length = exl[rownames(gdge$counts)])

gFit <- glmFit(gdge, model.matrix(~Group, data = df))
res <- residuals(gFit, type = "deviance")


# Batch correction and expression matrices.

nrgc <- RUVr(gdge$counts, 1:nrow(gdge$counts), 2, res)

gdge2 <- DGEList(nrgc$normalizedCounts, group = grp)
gdge2 <- calcNormFactors(gdge2)
gdge2 <- estimateDisp(gdge2)
gdge2$genes <- data.frame(Length = exl[rownames(gdge2$counts)])

rp2 <- rpkm(gdge2)
rp2 <- rp2[!matrixStats::rowAnyNAs(rp2), ]

cp2 <- cpm(gdge2)
cp2 <- cp2[!matrixStats::rowAnyNAs(cp2), ]

p <- outdir("rnaseq")

write.table(rp2, file.path(p, "gene_rpkm_matrix_ruvseq.tsv"),
  quote = FALSE, sep = "\t")

write.table(cp2, file.path(p, "gene_cpm_matrix_ruvseq.tsv"),
  quote = FALSE, sep = "\t")

